1	import java.util.Collections;
2	import java.util.Iterator;
3	import java.util.LinkedList;
4	import java.util.List;
5	import java.util.Random;
6	
7	/**
8	 * Represent a rectangular grid of field positions.
9	 * Each position is able to store a single animal and a single plant.
10	 *
11	 * @version 26/02/2022
12	 */
13	public class Field
14	{
15	    // A random number generator for providing random locations.
16	    private static final Random rand = Randomizer.getRandom();
17	    
18	    // The depth and width of the field.
19	    private int depth, width;
20	    // Storage for the animals.
21	    private GridSpace[][] field;
22	
23	    /**
24	     * Represent a field of the given dimensions.
25	     * 
26	     * @param depth The depth of the field.
27	     * @param width The width of the field.
28	     */
29	    public Field(int depth, int width)
30	    {
31	        this.depth = depth;
32	        this.width = width;
33	        field = new GridSpace[depth][width];
34	    }
35	    
36	    /**
37	     * Empty the field.
38	     */
39	    public void clear()
40	    {
41	        for(int row = 0; row < depth; row++) 
42	        {
43	            for(int col = 0; col < width; col++) 
44	            {
45	                field[row][col] = new GridSpace();
46	            }
47	        }
48	    }
49	    
50	    /**
51	     * Empty the object type of a field.
52	     * 
53	     * @param objectType Object type to clear
54	     */
55	    public void clear(Class objectType)
56	    {
57	        for(int row = 0; row < depth; row++) 
58	        {
59	            for(int col = 0; col < width; col++) 
60	            {
61	                field[row][col].clear(objectType);
62	            }
63	        }
64	    }
65	    
66	    /**
67	     * Clear the given location.
68	     * 
69	     * @param location Location The location to clear.
70	     * @param objectType Type of object to clear
71	     */
72	    public void clear(Location location, Class objectType)
73	    {
74	        field[location.getRow()][location.getCol()].clear(objectType);
75	    }
76	    
77	    /**
78	     * Place an animal at the given location.
79	     * If there is already an animal at the location it will
80	     * be lost.
81	     * 
82	     * @param animal The animal to be placed.
83	     * @param row Row coordinate of the location.
84	     * @param col Column coordinate of the location.
85	     */
86	    public void place(Object object, int row, int col)
87	    {
88	        place(object, new Location(row, col));
89	    }
90	    
91	    /**
92	     * Place an animal at the given location.
93	     * If there is already an animal at the location it will
94	     * be lost.
95	     * 
96	     * @param object The object to be placed.
97	     * @param location Where to place the animal.
98	     */
99	    public void place(Object object, Location location)
100	    {
101	        GridSpace gridSpace = field[location.getRow()][location.getCol()];
102	        
103	        if (gridSpace == null) {
104	            gridSpace = new GridSpace();
105	        }
106	        
107	        gridSpace.setObject(object);
108	    }
109	    
110	    /**
111	     * Return the animal at the given location, if any.
112	     * 
113	     * @param location Where in the field.
114	     * @param objectType Object type to fetch
115	     * 
116	     * @return The animal at the given location, or null if there is none.
117	     */
118	    public Object getObjectAt(Location location, Class objectType)
119	    {
120	        return getObjectAt(location.getRow(), location.getCol(), objectType);
121	    }
122	    
123	    /**
124	     * Return the animal at the given location, if any.
125	     * 
126	     * @param row The desired row.
127	     * @param col The desired column.
128	     * 
129	     * @return The animal at the given location, or null if there is none.
130	     */
131	    public Object getObjectAt(int row, int col, Class objectType)
132	    {
133	        if (field[row][col] == null)
134	        {
135	            field[row][col] = new GridSpace();
136	        }
137	        
138	        return field[row][col].getObject(objectType);
139	    }
140	    
141	    /**
142	     * Generate a random location that is adjacent to the
143	     * given location, or is the same location.
144	     * The returned location will be within the valid bounds
145	     * of the field.
146	     * 
147	     * @param location The location from which to generate an adjacency.
148	     * 
149	     * @return A valid location within the grid area.
150	     */
151	    public Location randomAdjacentLocation(Location location)
152	    {
153	        List<Location> adjacent = adjacentLocations(location);
154	        
155	        return adjacent.get(0);
156	    }
157	    
158	    /**
159	     * Get a shuffled list of the free adjacent locations.
160	     * 
161	     * @param location Get locations adjacent to this.
162	     * @param objectType Object type to avoid.
163	     * 
164	     * @return A list of free adjacent locations.
165	     */
166	    public List<Location> getFreeAdjacentLocations(Location location, Class objectType)
167	    {
168	        List<Location> free = new LinkedList<>();
169	        List<Location> adjacent = adjacentLocations(location);
170	        
171	        for(Location next : adjacent) 
172	        {
173	            if(getObjectAt(next, objectType) == null) 
174	            {
175	                free.add(next);
176	            }
177	        }
178	        
179	        return free;
180	    } 
181	    
182	    /**
183	     * Try to find a free location that is adjacent to the
184	     * given location. If there is none, return null.
185	     * The returned location will be within the valid bounds
186	     * of the field.
187	     * 
188	     * @param location The location from which to generate an adjacency.
189	     * @param objectType type to avoid.
190	     * 
191	     * @return A valid location within the grid area.
192	     */
193	    public Location freeAdjacentLocation(Location location, Class objectType)
194	    {
195	        // The available free ones.
196	        List<Location> free = getFreeAdjacentLocations(location, objectType);
197	        
198	        if(free.size() > 0) 
199	        {
200	            return free.get(0);
201	        }
202	        else
203	        {
204	            return null;
205	        }
206	    }
207	
208	    /**
209	     * Return a shuffled list of locations adjacent to the given one.
210	     * The list will not include the location itself.
211	     * All locations will lie within the grid.
212	     * 
213	     * @param location The location from which to generate adjacencies.
214	     * 
215	     * @return A list of locations adjacent to that given.
216	     */
217	    public List<Location> adjacentLocations(Location location)
218	    {
219	        assert location != null : "Null location passed to adjacentLocations";
220	        // The list of locations to be returned.
221	        List<Location> locations = new LinkedList<>();
222	        
223	        if(location != null)
224	        {
225	            int row = location.getRow();
226	            int col = location.getCol();
227	            
228	            for(int roffset = -1; roffset <= 1; roffset++) 
229	            {
230	                int nextRow = row + roffset;
231	                
232	                if(nextRow >= 0 && nextRow < depth) 
233	                {
234	                    for(int coffset = -1; coffset <= 1; coffset++) 
235	                    {
236	                        int nextCol = col + coffset;
237	                        
238	                        // Exclude invalid locations and the original location.
239	                        if(nextCol >= 0 && nextCol < width && (roffset != 0 || coffset != 0)) 
