155	     * 
156	     * Check whether or not this Plant is to give birth at this step.
157	     * New births will be made into free adjacent locations.
158	     * 
159	     * @param newPlants A list to return newly born Plants.
160	     */
161	    protected void populate(List<LivingOrganism> newPlants)
162	    {
163	        // Get a list of adjacent free locations.
164	        Field field = getField();
165	        List<Location> free = field.getFreeAdjacentLocations(getLocation(), Plant.class);
166	        
167	        // New plants are spread into adjacent locations.
168	        for(int b = 0; free.size() > 0; b++) 
169	        {
170	            newPlants.add(createOffspring(free));
171	        }
172	    }
