175	     * Used to instantiate baby plantlets
176	     * 
177	     * @param free List of free locations to spawn
178	     * @return Returns a new plant object.
179	     */
180	    private Plant createOffspring(List<Location> free) 
181	    {
182	        Location loc = free.remove(0);
183	        Plant offspring = null;
184	        
185	        offspring = new Plant(false, field, loc);
186	        
187	        return offspring;
188	    }
189	}
